#!/usr/bin/env node
// Keeps Ignifox for Android in step with the Linux browser: the same themes and the
// same new tab page. Run it after changing THEMES or anything in studio/content/newtab.
//   node tools/sync-android.mjs          write the generated files
//   node tools/sync-android.mjs --check  exit 1 if they are out of date
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { THEMES } from "../studio/content/prefs.sys.mjs";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const app = join(root, "android/app/src/main");
export const NEWTAB_FILES = ["index.html", "newtab.css", "newtab.js", "logo.svg", "MetalMania-Regular.ttf"];

const argb = hex => "0xFF" + hex.slice(1).toUpperCase() + ".toInt()";
const lum = hex => {
  const c = [1, 3, 5].map(i => parseInt(hex.slice(i, i + 2), 16) / 255).map(v => (v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4));
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
};
const onColor = hex => (lum(hex) > 0.4 ? "#000000" : "#ffffff");
const cap = k => k[0].toUpperCase() + k.slice(1);

export function themesKt() {
  const rows = Object.entries(THEMES).map(([k, t]) =>
    `        Palette("${k}", "${t.name}", ${t.dark}, ${argb(t.bg)}, ${argb(t.bg2)}, ${argb(t.bg3)}, ${argb(t.fg)}, ${argb(t.fgDim)}, ${argb(t.accent)}, ${argb(t.accent2)}, R.style.Igni_${cap(k)}),`);
  return `/* This Source Code Form is subject to the terms of the Mozilla Public
 * License, v. 2.0. If a copy of the MPL was not distributed with this
 * file, You can obtain one at http://mozilla.org/MPL/2.0/. */

// GENERATED by tools/sync-android.mjs from studio/content/prefs.sys.mjs. Do not edit.

package org.mozilla.reference.browser.ignifox

import org.mozilla.reference.browser.R

/** One Ignifox colour theme. The same list ships in the Linux browser. */
data class Palette(
    val key: String,
    val name: String,
    val dark: Boolean,
    val bg: Int,
    val bg2: Int,
    val bg3: Int,
    val fg: Int,
    val fgDim: Int,
    val accent: Int,
    val accent2: Int,
    val overlay: Int,
)

object Themes {
    val ALL: List<Palette> = listOf(
${rows.join("\n")}
    )
}
`;
}

export function themesXml() {
  const styles = Object.entries(THEMES).map(([k, t]) => `    <style name="Igni.${cap(k)}" parent="">
        <item name="colorPrimary">${t.accent}</item>
        <item name="colorOnPrimary">${onColor(t.accent)}</item>
        <item name="colorPrimaryDark">${t.bg}</item>
        <item name="colorAccent">${t.accent}</item>
        <item name="colorSecondary">${t.accent}</item>
        <item name="colorOnSecondary">${onColor(t.accent)}</item>
        <item name="colorControlActivated">${t.accent}</item>
        <item name="colorSurface">${t.bg2}</item>
        <item name="colorOnSurface">${t.fg}</item>
        <item name="colorOnSurfaceVariant">${t.fgDim}</item>
        <item name="colorSurfaceContainer">${t.bg2}</item>
        <item name="colorSurfaceContainerHigh">${t.bg3}</item>
        <item name="colorSurfaceContainerHighest">${t.bg3}</item>
        <item name="colorSurfaceVariant">${t.bg3}</item>
        <item name="colorOutline">${t.fgDim}</item>
        <item name="android:colorBackground">${t.bg}</item>
        <item name="android:windowBackground">@color/igni_${k}_bg</item>
        <item name="android:navigationBarColor">${t.bg}</item>
        <item name="android:textColorPrimary">${t.fg}</item>
        <item name="android:textColorSecondary">${t.fgDim}</item>
        <item name="android:textColorLink">${t.accent}</item>
    </style>`);
  const colors = Object.entries(THEMES).map(([k, t]) => `    <color name="igni_${k}_bg">${t.bg}</color>`);
  const names = Object.values(THEMES).map(t => `        <item>${t.name}</item>`);
  const keys = Object.keys(THEMES).map(k => `        <item>${k}</item>`);
  return `<?xml version="1.0" encoding="utf-8"?>
<!-- GENERATED by tools/sync-android.mjs from studio/content/prefs.sys.mjs. Do not edit. -->
<resources xmlns:tools="http://schemas.android.com/tools" tools:ignore="UnusedResources">
${colors.join("\n")}

${styles.join("\n")}

    <string-array name="igni_theme_names" translatable="false">
${names.join("\n")}
    </string-array>
    <string-array name="igni_theme_keys" translatable="false">
${keys.join("\n")}
    </string-array>
</resources>
`;
}

export function outputs() {
  const out = new Map();
  out.set(join(app, "java/org/mozilla/reference/browser/ignifox/Themes.kt"), Buffer.from(themesKt()));
  out.set(join(app, "res/values/ignifox_themes.xml"), Buffer.from(themesXml()));
  // On Android the page is a read-only file inside the APK, so its settings ride in the
  // address after "#" instead of a config.js written next to it.
  out.set(join(app, "assets/newtab/config.js"), Buffer.from(
    "// GENERATED by tools/sync-android.mjs. Do not edit.\n" +
    "try {\n  window.IGNI_NEWTAB = JSON.parse(decodeURIComponent(location.hash.slice(1)));\n" +
    "} catch (e) {\n  window.IGNI_NEWTAB = { platform: \"android\", noAutofocus: true };\n}\n"));
  for (const f of NEWTAB_FILES) {
    out.set(join(app, "assets/newtab", f), readFileSync(join(root, "studio/content/newtab", f)));
  }
  return out;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes("--check");
  let stale = 0;
  for (const [path, data] of outputs()) {
    const same = existsSync(path) && readFileSync(path).equals(data);
    if (same) continue;
    stale++;
    if (check) console.error("out of date: " + path.slice(root.length + 1));
    else { mkdirSync(dirname(path), { recursive: true }); writeFileSync(path, data); console.log("wrote " + path.slice(root.length + 1)); }
  }
  if (check && stale) { console.error("run: node tools/sync-android.mjs"); process.exit(1); }
}
